const LOGO_DATA_URI = `data:image/svg+xml;base64,${Buffer.from(LOGO_SVG).toString('base64')}`

let fontsCache: { regular: ArrayBuffer; bold: ArrayBuffer } | null = null

async function getFonts() {
  if (fontsCache) return fontsCache
  const [regular, bold] = await Promise.all([
    fetch('https://cdn.jsdelivr.net/npm/@fontsource/inter@5/files/inter-latin-400-normal.woff').then(r => r.arrayBuffer()),
    fetch('https://cdn.jsdelivr.net/npm/@fontsource/inter@5/files/inter-latin-700-normal.woff').then(r => r.arrayBuffer()),
  ])
  fontsCache = { regular, bold }
  return fontsCache
}

export async function generarImagenDolar({ blue, oficial, fecha, tipo }: Params): Promise<Buffer> {
  const fonts = await getFonts()

  const response = new ImageResponse(
    (
      <div
        style={{
          width: 1080,
          height: 1920,
          background: tipo === 'inicio' ? '#001810' : '#110000',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          padding: '40px 80px',
          fontFamily: 'Inter',
          gap: '130px',
          
        }}
      >
        {/* Título */}
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '16px', marginBottom: '48px' }}>
          <div style={{ fontSize: 33, fontWeight: 700, color: tipo === 'inicio' ? '#008b5d' : '#bb0000', textTransform: 'uppercase', letterSpacing: '0.2em' }}>
            {tipo === 'inicio' ? 'Apertura' : 'Cierre'}
          </div>
          <div style={{ width: 400, height: 1, background: tipo === 'inicio' ? '#008b5d' : '#bb0000', alignSelf: 'center', marginTop: '18px', marginBottom: '32px' }} />
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img src={LOGO_DATA_URI} width={800} height={89} alt="Color del Dólar" />
          <div style={{ fontSize: 28, color: '#71717a' }}>{fecha}</div>
        </div>

        {/* Cards */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '32px', width: '100%' }}>
          {/* Blue */}
          <div
            style={{
              background: 'rgba(45, 86, 178, 0.08)',
              border: '1px solid rgba(45, 86, 178, 0.22)',
              borderRadius: '24px',
              padding: '52px 60px',
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              gap: '36px',
            }}
          >
            <div style={{ fontSize: 24, fontWeight: 700, color: '#6b8fe8', textTransform: 'uppercase', letterSpacing: '0.12em' }}>
              Dólar Blue
            </div>
            <div style={{ display: 'flex', gap: '80px', alignItems: 'center' }}>
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '10px' }}>
                <div style={{ fontSize: 20, color: '#71717a', textTransform: 'uppercase', letterSpacing: '0.08em' }}>Compra</div>
                <div style={{ fontSize: 72, fontWeight: 700, color: '#6b8fe8' }}>
                  {`$${blue.compra.toLocaleString('es-AR')}`}
                </div>
              </div>
              <div style={{ width: 1, height: 80, background: 'rgba(45, 86, 178, 0.22)' }} />
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '10px' }}>
                <div style={{ fontSize: 20, color: '#71717a', textTransform: 'uppercase', letterSpacing: '0.08em' }}>Venta</div>
                <div style={{ fontSize: 72, fontWeight: 700, color: '#9ab4f4' }}>
                  {`$${blue.venta.toLocaleString('es-AR')}`}
                </div>
              </div>
            </div>
          </div>

          {/* Oficial */}
          <div
            style={{
              background: 'rgba(76, 191, 0, 0.08)',
              border: '1px solid rgba(76, 191, 0, 0.22)',
              borderRadius: '24px',
              padding: '52px 60px',
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              gap: '36px',
            }}
          >
            <div style={{ fontSize: 24, fontWeight: 700, color: '#8bda00', textTransform: 'uppercase', letterSpacing: '0.12em' }}>
              Dólar Oficial
            </div>
            <div style={{ display: 'flex', gap: '80px', alignItems: 'center' }}>
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '10px' }}>
                <div style={{ fontSize: 20, color: '#71717a', textTransform: 'uppercase', letterSpacing: '0.08em' }}>Compra</div>
                <div style={{ fontSize: 72, fontWeight: 700, color: '#8bda00' }}>
                  {`$${oficial.compra.toLocaleString('es-AR')}`}
                </div>
              </div>
              <div style={{ width: 1, height: 80, background: 'rgba(76, 191, 0, 0.22)' }} />
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '10px' }}>
                <div style={{ fontSize: 20, color: '#71717a', textTransform: 'uppercase', letterSpacing: '0.08em' }}>Venta</div>
                <div style={{ fontSize: 72, fontWeight: 700, color: '#b0ea4a' }}>
                  {`$${oficial.venta.toLocaleString('es-AR')}`}
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Footer */}
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '12px' }}>
          <div style={{ fontSize: 28, color: '#dadada', textAlign: 'center', fontWeight: 700 }}>
            COLORDELDOLAR.COM.AR
          </div>
          <div style={{ width: 600, height: 1, background: 'rgba(255,255,255,0.12)', alignSelf: 'center', marginTop: '32px', marginBottom: '32px' }} />
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '10px', fontSize: 24, color: '#dadada', background: 'rgba(255,255,255,0.08)', border: '1px solid rgba(255,255,255,0.15)', borderRadius: '100px', width: 450, padding: '14px 28px', marginBottom: '20px' }}>
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img src={`data:image/svg+xml;base64,${Buffer.from('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path fill="#dadada" d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z"/></svg>').toString('base64')}`} width={24} height={24} alt="X" />
            @colordeldolar
          </div>
          <div style={{ fontSize: 20, color: '#adadad', textAlign: 'center', maxWidth: 600 }}>
            Cotización del dólar blue y oficial todos los días hábiles, directo en X.
          </div>
        </div>
      </div>
    ),
    {
      width: 1080,
      height: 1920,
      fonts: [
        { name: 'Inter', data: fonts.regular, weight: 400 },
        { name: 'Inter', data: fonts.bold, weight: 700 },
      ],
    }
  )

  return Buffer.from(await response.arrayBuffer())
}
